// Generates .github/ISSUE_TEMPLATE/device-answers.yml from data/questions.json,
// so the form and the card always ask the same questions with the same
// answers (device-answers.cjs maps the form's labels back to ids).
// Run: node .github/scripts/build-issue-form.cjs
"use strict";

const fs = require("fs");
const path = require("path");
const { loadQuestions, typeLabel } = require("./device-answers.cjs");

const q = loadQuestions(path.join(__dirname, "..", ".."));
const OTHER = "Other (please say below)";
const y = (s) => JSON.stringify(String(s)); // JSON strings are valid YAML scalars

const lines = [];
const push = (...l) => lines.push(...l);
push(
  "# Generated by .github/scripts/build-issue-form.cjs from data/questions.json. Don't edit by hand.",
  `name: ${y("Device answers: how a device behaves")}`,
  `description: ${y("Tell the next person how a Zigbee device behaves in real use: things a capability scan can't show.")}`,
  `title: ${y("[Device Answers] <manufacturer> <model>")}`,
  "labels: [device-answers]",
  "body:",
  "  - type: markdown",
  "    attributes:",
  `      value: ${y(
    "Answer for **one device you own**. Every question is optional apart from the device, its firmware and what you use it for. Choose \"Doesn't apply\" for anything that doesn't fit. Answers are kept per firmware version and shown as counts, never as a verdict. Don't include names, places or addresses: free text is reviewed before it's shown.\n\nUsing ZHA Bindings Manager? Its device side panel asks only the questions that apply and fills in the firmware for you."
  )}`
);
const input = (label, desc, required = true) =>
  push("  - type: input", "    attributes:", `      label: ${y(label)}`, ...(desc ? [`      description: ${y(desc)}`] : []), "    validations:", `      required: ${required}`);
const dropdown = (label, options, { desc = null, required = false } = {}) => {
  push("  - type: dropdown", "    attributes:", `      label: ${y(label)}`);
  if (desc) push(`      description: ${y(desc)}`);
  push("      options:", ...options.map((o) => `        - ${y(o)}`), "    validations:", `      required: ${required}`);
};

input("Manufacturer", "Exactly as your Zigbee system shows it, e.g. IKEA of Sweden");
input("Model", "Exactly as your Zigbee system shows it, e.g. RODRET Dimmer");
input("Firmware version", "The device's firmware (software build) version, e.g. 1.0.5 or 0x00000017");
dropdown("Device type", q.device_types.map((t) => t.label), { required: true });
dropdown(
  q.use.text,
  [...Object.entries(q.use.answers_by_type).flatMap(([t, list]) => list.map((a) => `${typeLabel(q, t)}: ${a.label}`)), OTHER],
  { desc: q.use.help, required: true }
);
for (const question of q.questions) {
  const opts = question.answers.map((a) => a.label);
  if (question.allow_other) opts.push(question.other_label || OTHER);
  opts.push("Doesn't apply");
  const only = question.types.length === q.device_types.length ? "" : `Only for: ${question.types.map((t) => typeLabel(q, t)).join(", ")}.`;
  dropdown(question.text, opts, { desc: [question.help, only].filter(Boolean).join(" ") || null });
}
push("  - type: textarea", "    attributes:", `      label: ${y('If you chose an "other" answer, tell us more')}`, `      description: ${y(`Up to ${q.free_text_max} characters.`)}`, "    validations:", "      required: false");
dropdown(q.rating.text, Object.entries(q.rating.labels).map(([n, l]) => `${n} – ${l}`), { desc: "Optional. Subjective, so it's shown as a spread of ratings, and only averaged once 3 people have rated." });
for (const c of q.context) dropdown(c.text, c.answers.map((a) => a.label), { desc: c.help || null });
push("  - type: textarea", "    attributes:", `      label: ${y(q.tip.text)}`, `      description: ${y(q.tip.help)}`, "    validations:", "      required: false");

const out = path.join(__dirname, "..", "ISSUE_TEMPLATE", "device-answers.yml");
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, lines.join("\n") + "\n");
console.log(`Wrote ${path.relative(process.cwd(), out)} (${q.questions.length} questions).`);
